{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "nui-hunter-instance-model-v1",
  "title": "Instance Model Schema — Operator-Level Specifics",
  "description": "Each model in a verdict MUST have instance-level fields: specific product, buyers with contacts, suppliers with prices, price spread with sources, first cold message, competitor count. Categories without instances are REJECTED.",
  "type": "object",
  "required": [
    "sub_niche_name",
    "specific_product",
    "specific_buyers",
    "specific_suppliers",
    "price_spread",
    "first_action_message",
    "competitor_count_exact_niche"
  ],
  "properties": {
    "sub_niche_name": {
      "type": "string",
      "minLength": 10,
      "description": "Exact micro-niche name. NOT a category. BAD: 'Export Sourcing'. GOOD: 'Vietnamese cashew W320 to Thai snack manufacturers'."
    },
    "specific_product": {
      "type": "string",
      "minLength": 10,
      "description": "Named product/service with specs. BAD: 'coffee'. GOOD: 'Robusta S16 screen, 13% moisture, Grade 1, Dak Lak origin'."
    },
    "specific_buyers": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "company", "contact_method", "why_they_buy"],
        "properties": {
          "name": {
            "type": "string",
            "description": "Person name or company name. Must be a real, verifiable entity."
          },
          "company": {
            "type": "string",
            "description": "Company name. If person name given, this is their employer."
          },
          "contact_method": {
            "type": "string",
            "description": "LinkedIn URL, email, website contact form, Alibaba chat, etc."
          },
          "why_they_buy": {
            "type": "string",
            "description": "Evidence they buy this product: import records, LinkedIn post, website product page, etc."
          },
          "verified_date": {
            "type": "string",
            "format": "date",
            "description": "Date this contact info was verified."
          },
          "source_url": {
            "type": "string",
            "description": "URL where buyer info was found."
          }
        }
      }
    },
    "specific_suppliers": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "location", "price", "contact_method"],
        "properties": {
          "name": {
            "type": "string",
            "description": "Factory/supplier company name. Must be verifiable."
          },
          "location": {
            "type": "string",
            "description": "City, province, country."
          },
          "price": {
            "type": "string",
            "description": "Exact price with unit and terms. E.g., '$2,400/ton FOB HCM'."
          },
          "contact_method": {
            "type": "string",
            "description": "Email, Alibaba link, phone, factory address."
          },
          "verified_date": {
            "type": "string",
            "format": "date"
          },
          "source_url": {
            "type": "string"
          }
        }
      }
    },
    "price_spread": {
      "type": "object",
      "required": ["buy_price", "sell_price", "margin_pct", "verified_date", "source_url"],
      "properties": {
        "buy_price": {
          "type": "string",
          "description": "Price from supplier with unit. E.g., '$2,400/ton FOB'."
        },
        "sell_price": {
          "type": "string",
          "description": "Price buyer pays with unit. E.g., '$3,800/ton CIF'."
        },
        "logistics_cost": {
          "type": "string",
          "description": "Estimated freight + customs + handling. E.g., '$600/ton'."
        },
        "margin_pct": {
          "type": "number",
          "description": "Net margin percentage after all costs."
        },
        "margin_absolute": {
          "type": "string",
          "description": "Net margin in absolute terms. E.g., '$800/ton'."
        },
        "verified_date": {
          "type": "string",
          "format": "date"
        },
        "source_url": {
          "type": "string",
          "description": "URL(s) where prices were found."
        }
      }
    },
    "first_action_message": {
      "type": "string",
      "minLength": 50,
      "description": "Ready-to-send cold message. Personalized to first buyer above. In buyer's language. Under 150 words. Copy-paste ready."
    },
    "competitor_count_exact_niche": {
      "type": "object",
      "required": ["count", "names"],
      "properties": {
        "count": {
          "type": "integer",
          "description": "How many others do THIS EXACT sub-niche (not the broad category)."
        },
        "names": {
          "type": "array",
          "items": {"type": "string"},
          "description": "Top 2-3 competitor names if found."
        },
        "differentiation": {
          "type": "string",
          "description": "Your angle vs competitors."
        }
      }
    },
    "kill_criterion": {
      "type": "string",
      "description": "Specific to THIS sub-niche. Not generic. E.g., '0 responses from [buyer1, buyer2, buyer3] after 15 personalized emails in 14 days -> pivot product'."
    },
    "instance_completeness": {
      "type": "string",
      "enum": ["COMPLETE", "PARTIAL", "INCOMPLETE"],
      "description": "COMPLETE: all fields verified. PARTIAL: some fields tagged [INSTANCE_INCOMPLETE]. INCOMPLETE: major gaps."
    }
  }
}

