import sys, json, io, tempfile
from pathlib import Path

# Minimal stubs to import the functions we need
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")

# Inline the functions we need to test
def normalize_verdict_class(raw):
    if not isinstance(raw, str):
        return "UNKNOWN"
    upper = raw.upper()
    for tag in ("HARD_KILL", "KILL", "EXPLORATION_ONGOING", "EXPLORATION_COMPLETE",
                "MOUNTAIN_CANDIDATE", "PROVISIONAL_MOUNTAIN", "MOUNTAIN",
                "COMMERCE_ENTRY", "CONDITIONAL_GO", "CONDITIONAL",
                "SIDE_HUSTLE", "INSUFFICIENT_SIGNAL", "TEST"):
        if tag in upper:
            return tag
    return "UNKNOWN"

INSTANCE_REQUIRED_CLASSES = {
    "MOUNTAIN_CANDIDATE", "PROVISIONAL_MOUNTAIN", "MOUNTAIN",
    "COMMERCE_ENTRY", "CONDITIONAL_GO", "CONDITIONAL", "SIDE_HUSTLE",
}
INSTANCE_REQUIRED_FIELDS = [
    "sub_niche_name", "specific_product", "specific_buyers",
    "specific_suppliers", "price_spread", "first_action_message",
    "competitor_count_exact_niche",
]

def check_instance_gate(case, skip_instance_gate=False):
    verdict_class_raw = (case.get("verdict_class") or case.get("verdict") or "")
    verdict_class = normalize_verdict_class(verdict_class_raw)
    if verdict_class not in INSTANCE_REQUIRED_CLASSES:
        return {"gate_passed": True, "reason": f"Class '{verdict_class}' exempt"}
    models = case.get("instance_models") or case.get("models") or []
    if not models:
        if skip_instance_gate:
            return {"gate_passed": True, "reason": "bypass"}
        raise ValueError(f"Instance gate BLOCKED: no instance_models for class={verdict_class}")
    all_missing = []
    for i, model in enumerate(models):
        model_missing = []
        for field in INSTANCE_REQUIRED_FIELDS:
            val = model.get(field)
            if val is None:
                model_missing.append(field)
            elif isinstance(val, str) and len(val.strip()) < 5:
                model_missing.append(f"{field} (too short)")
            elif isinstance(val, list) and len(val) == 0:
                model_missing.append(f"{field} (empty)")
        if model_missing:
            all_missing.append({"model_index": i, "missing": model_missing})
    if all_missing:
        if skip_instance_gate:
            return {"gate_passed": True, "reason": "bypass"}
        raise ValueError(f"Instance gate BLOCKED: {all_missing}")
    return {"gate_passed": True, "reason": f"All {len(models)} models OK"}

# Tests
print("Test 1: KILL exempted")
r = check_instance_gate({"verdict_class": "KILL"})
print(f"  PASS: {r['gate_passed']} — {r['reason']}")

print("\nTest 2: MOUNTAIN_CANDIDATE without models")
try:
    check_instance_gate({"verdict_class": "MOUNTAIN_CANDIDATE"})
    print("  ERROR: should have raised")
except ValueError as e:
    print(f"  BLOCKED: {str(e)[:60]}")

print("\nTest 3: MOUNTAIN_CANDIDATE with incomplete model")
