        {"sub_niche_name": "test niche detailed", "specific_product": "test product detailed"}
    ]})
    print("  ERROR: should have raised")
except ValueError as e:
    print(f"  BLOCKED: {str(e)[:80]}")

print("\nTest 4: MOUNTAIN_CANDIDATE with full model")
r = check_instance_gate({"verdict_class": "MOUNTAIN_CANDIDATE", "instance_models": [{
    "sub_niche_name": "Vietnamese cashew W320 to Thai snack mfg",
    "specific_product": "Cashew kernel W320 grade Binh Phuoc",
    "specific_buyers": [{"name": "Tong Garden", "company": "TG Co", "contact_method": "email", "why_they_buy": "snacks"}],
    "specific_suppliers": [{"name": "BP Cashew", "location": "Binh Phuoc", "price": "$2400/ton", "contact_method": "email"}],
    "price_spread": {"buy_price": "$2400", "sell_price": "$3800", "margin_pct": 15.8, "verified_date": "2026-05-17", "source_url": "https://x"},
    "first_action_message": "Dear procurement team, we are a Binh Phuoc cashew processor offering W320 grade at competitive FOB pricing...",
    "competitor_count_exact_niche": {"count": 5, "names": ["VN Cashew Export"]}
}]})
print(f"  PASS: {r['gate_passed']} — {r['reason']}")

print("\nTest 5: SIDE_HUSTLE requires instances too")
try:
    check_instance_gate({"verdict_class": "SIDE_HUSTLE"})
    print("  ERROR: should have raised")
except ValueError as e:
    print(f"  BLOCKED: {str(e)[:60]}")

print("\nAll tests passed!")
